const assert=require('node:assert/strict');const fs=require('node:fs/promises');const path=require('node:path');const {chromium}=require(process.env.PDFPILOT_PLAYWRIGHT_MODULE||'playwright');
const base=process.argv[2]||'http://127.0.0.1:4400',out=path.resolve(process.argv[3]||'docs/product-completion/qa-built-launch-routes-2026-10-04');
(async()=>{await fs.mkdir(out,{recursive:true});const report={base,http:[],languageControls:[]};const slugs=['flatten-pdf','base64-encode','base64-decode','url-encode','url-decode'];for(const slug of slugs){for(const route of ['/'+slug,'/es/'+slug]){const r=await fetch(base+route);const body=await r.text();const robots=[r.headers.get('x-robots-tag'),...Array.from(body.matchAll(/<meta[^>]+name="robots"[^>]+content="([^"]+)"/g),m=>m[1])].filter(Boolean);const record={route,status:r.status,robots};report.http.push(record);assert.equal(r.status,route.startsWith('/es/')?404:200);if(route.startsWith('/es/'))assert.ok(robots.some(x=>/noindex/i.test(x)));}}const gated=await fetch(base+'/rotate-image');const html=await gated.text();report.http.push({route:'/rotate-image',status:gated.status,robots:[...html.matchAll(/<meta[^>]+name="robots"[^>]+content="([^"]+)"/g)].map(m=>m[1])});assert.equal(gated.status,404);assert.ok(/name="robots"[^>]*content="[^"]*noindex/.test(html)||/noindex/.test(gated.headers.get('x-robots-tag')||''));
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});try{const page=await browser.newPage();for(const slug of [...slugs,'merge-pdf','es/merge-pdf']){await page.goto(base+'/'+slug,{waitUntil:'domcontentloaded'});await page.getByRole('button',{name:/Switch to (dark|light) mode|Cambiar a modo/}).waitFor().catch(()=>{});const language=page.getByRole('button',{name:/Choose language|Elegir idioma|Seleccionar idioma/});const count=await language.count();report.languageControls.push({slug,count});assert.equal(count,slugs.includes(slug)?0:1);}}finally{await browser.close();}report.status='passed';await fs.writeFile(path.join(out,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));})().catch(e=>{console.error(e);process.exitCode=1;});
